package singleton

import (
	"reflect"
	"strings"
	"sync"

	"github.com/navidrome/navidrome/log"
)

var (
	instances      = make(map[string]interface{})
	getOrCreateC   = make(chan *entry, 1)
	typedInstances = struct {
		sync.Mutex
		instances map[reflect.Type]*typedEntry
	}{instances: make(map[reflect.Type]*typedEntry)}
)

type entry struct {
	constructor func() interface{}
	object      interface{}
	resultC     chan interface{}
}

type typedEntry struct {
	once   sync.Once
	object interface{}
}

// GetInstance returns the singleton instance for T, creating it with
// constructor on the first call.
func GetInstance[T any](constructor func() T) T {
	typ := reflect.TypeOf((*T)(nil)).Elem()

	typedInstances.Lock()
	instance := typedInstances.instances[typ]
	if instance == nil {
		instance = &typedEntry{}
		typedInstances.instances[typ] = instance
	}
	typedInstances.Unlock()

	instance.once.Do(func() {
		instance.object = constructor()
	})

	return instance.object.(T)
}

// Get returns an existing instance of object. If it is not yet created, calls `constructor`, stores the
// result for future calls and return it
func Get(object interface{}, constructor func() interface{}) interface{} {
	e := &entry{
		constructor: constructor,
		object:      object,
		resultC:     make(chan interface{}),
	}
	getOrCreateC <- e
	return <-e.resultC
}

func init() {
	go func() {
		for {
			e := <-getOrCreateC
			name := reflect.TypeOf(e.object).String()
			name = strings.TrimPrefix(name, "*")
			v, created := instances[name]
			if !created {
				v = e.constructor()
				log.Trace("Created new singleton", "object", name, "instance", v)
				instances[name] = v
			}
			e.resultC <- v
		}
	}()
}
package singleton_test

import (
	"sync"
	"sync/atomic"
	"testing"

	"github.com/google/uuid"

	"github.com/navidrome/navidrome/utils/singleton"
	. "github.com/onsi/ginkgo/v2"
	. "github.com/onsi/gomega"
)

func TestSingleton(t *testing.T) {
	RegisterFailHandler(Fail)
	RunSpecs(t, "Singleton Suite")
}

var _ = Describe("Get", func() {
	type T struct{ id string }
	var numInstances int
	constructor := func() interface{} {
		numInstances++
		return &T{id: uuid.NewString()}
	}

	It("calls the constructor to create a new instance", func() {
		instance := singleton.Get(T{}, constructor)
		Expect(numInstances).To(Equal(1))
		Expect(instance).To(BeAssignableToTypeOf(&T{}))
	})

	It("does not call the constructor the next time", func() {
		instance := singleton.Get(T{}, constructor)
		newInstance := singleton.Get(T{}, constructor)

		Expect(newInstance.(*T).id).To(Equal(instance.(*T).id))
		Expect(numInstances).To(Equal(1))
	})

	It("does not call the constructor even if a pointer is passed as the object", func() {
		instance := singleton.Get(T{}, constructor)
		newInstance := singleton.Get(&T{}, constructor)

		Expect(newInstance.(*T).id).To(Equal(instance.(*T).id))
		Expect(numInstances).To(Equal(1))
	})

	It("only calls the constructor once when called concurrently", func() {
		const maxCalls = 2000
		var numCalls int32
		start := sync.WaitGroup{}
		start.Add(1)
		prepare := sync.WaitGroup{}
		prepare.Add(maxCalls)
		done := sync.WaitGroup{}
		done.Add(maxCalls)
		for i := 0; i < maxCalls; i++ {
			go func() {
				start.Wait()
				singleton.Get(T{}, constructor)
				atomic.AddInt32(&numCalls, 1)
				done.Done()
			}()
			prepare.Done()
		}
		prepare.Wait()
		start.Done()
		done.Wait()

		Expect(numCalls).To(Equal(int32(maxCalls)))
		Expect(numInstances).To(Equal(1))
	})
})

var _ = Describe("GetInstance", func() {
	type instance struct{ id int }

	It("creates and reuses instances separately for value and pointer types", func() {
		valueCreations := 0
		value := singleton.GetInstance(func() instance {
			valueCreations++
			return instance{id: 1}
		})
		valueAgain := singleton.GetInstance(func() instance {
			valueCreations++
			return instance{id: 2}
		})

		Expect(valueAgain).To(Equal(value))
		Expect(valueCreations).To(Equal(1))

		pointerCreations := 0
		pointer := singleton.GetInstance(func() *instance {
			pointerCreations++
			return &instance{id: 3}
		})
		pointerAgain := singleton.GetInstance(func() *instance {
			pointerCreations++
			return &instance{id: 4}
		})

		Expect(pointerAgain).To(BeIdenticalTo(pointer))
		Expect(pointerCreations).To(Equal(1))
		Expect(value.id).To(Equal(1))
		Expect(pointer.id).To(Equal(3))
	})

	It("creates one instance across 20,000 concurrent calls", func() {
		type concurrentInstance struct{}
		const calls = 20000

		var creations int32
		start := make(chan struct{})
		instances := make(chan *concurrentInstance, calls)
		var done sync.WaitGroup
		done.Add(calls)

		for i := 0; i < calls; i++ {
			go func() {
				defer done.Done()
				<-start
				instances <- singleton.GetInstance(func() *concurrentInstance {
					atomic.AddInt32(&creations, 1)
					return &concurrentInstance{}
				})
			}()
		}

		close(start)
		done.Wait()
		close(instances)

		var first *concurrentInstance
		for current := range instances {
			if first == nil {
				first = current
				continue
			}
			Expect(current).To(BeIdenticalTo(first))
		}
		Expect(atomic.LoadInt32(&creations)).To(Equal(int32(1)))
	})
})

